begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('private','order_refund_operations','persist a logical operation before a provider request');
select has_function('public','server_claim_owned_refund',array['uuid','uuid','uuid'],'existing writer has durable dispatch claim');
\ir helpers/spec09_refund_setup.inc
select pg_temp.record_and_fulfill('spec09paid','spec09paid',id,session_id) is not null from fulfillment_orders;
reset role;
create function pg_temp.summary() returns jsonb language sql as $$select public.get_organizer_refund_status('a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders where kind='clean'));$$;
select is(pg_temp.summary()->>'state','eligible','fulfilled paid order eligible');
select is(pg_temp.summary()->>'totalMinor','7000','immutable whole amount');
select ok(not (pg_temp.summary()::text ~ 'stripe_|paymentIntent|chargeId|token|hash|credential'),'owner summary excludes private provider and credential material');
select throws_ok($$select public.server_claim_owned_refund('a6100000-0000-4000-8000-000000000002','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders))$$,'42501','Order unavailable','wrong owner cannot claim');
select throws_ok($$select public.server_claim_owned_refund('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000002',(select id from fulfillment_orders))$$,'42501','Order unavailable','wrong event cannot claim');
select is((select count(*) from private.order_refund_operations where order_id=(select id from fulfillment_orders)),0::bigint,'unauthorized has no operation effect');
select is(public.server_claim_owned_refund('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders))->>'dispatch','true','first call alone permits existing writer');
select is(public.server_claim_owned_refund('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders))->>'dispatch','false','duplicate does not dispatch');
select is((select count(*) from private.order_refund_operations where order_id=(select id from fulfillment_orders)),1::bigint,'one operation persisted');
select is(pg_temp.summary()->>'state','submitting','pre-provider request is durable');
select is((select status from public.orders where id=(select id from fulfillment_orders)),'paid','submission cannot mark refunded');
select is((select count(*) from public.tickets where status='valid' and order_id=(select id from fulfillment_orders)),3::bigint,'submission cannot invalidate admissions');
select is((private.ticket_email_source('paid_order',(select id from fulfillment_orders))->>'eligible'),'false','unresolved operation prevents new admission resend');
select throws_ok($$update private.order_refund_operations set idempotency_key='new-key'$$,'P0001','Immutable refund operation','no key rotation');
select public.server_note_refund_observation('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders),'unknown',null);
select is(pg_temp.summary()->>'state','unknown','timeout remains durable unknown');
select is(pg_temp.summary()->>'action','reconcile','timeout offers recovery only');
select is(public.server_claim_owned_refund('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders))->>'dispatch','false','unknown never creates another refund');
select public.server_note_refund_observation('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders),'processing','re_spec09');
select is(pg_temp.summary()->>'state','processing','provider acceptance is processing not completed');
select public.server_note_refund_observation('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders),'review','re_other');
select is(pg_temp.summary()->>'state','review','contradictory refund identities require review');
select is((select stripe_refund_id from private.order_refund_operations where order_id=(select id from fulfillment_orders)),'re_spec09','original provider identity retained');
select throws_ok($$select public.server_note_refund_observation('a6100000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000001',(select id from fulfillment_orders),'completed','re_spec09')$$,'22023','Invalid refund observation','provider callback cannot assert financial completion');
select ok(not has_table_privilege('authenticated','private.order_refund_operations','select'),'browser has no operation table read');
select ok(not has_function_privilege('authenticated','public.server_claim_owned_refund(uuid,uuid,uuid)','execute'),'browser cannot assert organizer authority');
select set_config('request.jwt.claim.sub','a6100000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.summary()$$,'42501','Order unavailable','owner read rejects account switch');
select * from finish();rollback;
